506	  private readonly _handleScroll = (): void => {
507	    if (!this._feedState.hasMore) return;
508	    if (this._loading) return;
509	    const list = this._elements.gridList;
510	    if (!list) return;
511	    const thresholdReached = this._isThresholdReached(list);
512	    if (!thresholdReached) {
513	      this._thresholdArmed = true;
514	      return;
515	    }
516	    if (!this._thresholdArmed) return;
517	    this._thresholdArmed = false;
518	    void this._loadMore();
519	  };
520	
521	  private _isThresholdReached(list: HTMLElement): boolean {
522	    const rect = list.getBoundingClientRect();
523	    return (
